const resp = $input.first().json;
const prior = $('Build One-Pager Prompt').first().json;
const content = resp && resp.choices && resp.choices[0] && resp.choices[0].message ? resp.choices[0].message.content : null;
let raw = {};
let parseError = false;
try { raw = JSON.parse(content); } catch (e) { raw = {}; parseError = true; }

const KEY_ALIASES = {
  name: ['name', 'venture_name', 'title', 'idea_name'],
  one_liner: ['one_liner', 'oneliner', 'one_line', 'summary'],
  what_it_is: ['what_it_is', 'what_is_it', 'whatitis', 'what_is'],
  what_it_takes: ['what_it_takes', 'what_takes', 'whatittakes', 'what_it_take', 'requirements'],
  why_it_might_fail: ['why_it_might_fail', 'why_might_it_fail', 'why_it_may_fail', 'failure_mode'],
  why_relevant: ['why_relevant', 'whyrelevant', 'why_defensible', 'relevance'],
  firm_lens: ['firm_lens', 'firmlens', 'firm_angle'],
  owning_entity: ['owning_entity', 'owner', 'executing_entity', 'entity'],
  execution_level: ['execution_level', 'level'],
  act_watch_kill: ['act_watch_kill', 'recommendation', 'decision'],
  next_90_days: ['next_90_days', 'ninety_day_step', 'next_steps', 'next_step']
};

function pickField(obj, aliases) {
  for (const key of aliases) {
    if (obj && typeof obj[key] === 'string' && obj[key].trim().length > 0) return obj[key];
  }
  return '';
}

const parsed = {};
const missingFields = [];
for (const canonical of Object.keys(KEY_ALIASES)) {
  const value = pickField(raw, KEY_ALIASES[canonical]);
  parsed[canonical] = value;
  if (!value && canonical !== 'next_90_days') missingFields.push(canonical);
}

return [{ json: {
  idea_id: prior.idea_id,
  idea_number: prior.idea_number,
  source_json: prior.source_json,
  abstraction_json: prior.abstraction_json,
  national_context_json: prior.national_context_json,
  scoring_json: prior.scoring_json,
  generated_fields: parsed,
  parse_error: parseError,
  generation_missing_fields: missingFields
} }];

const item = $input.first().json;
const a = item.abstraction_json || {};
const dc = item.national_context_json || {};
const sc = item.scoring_json || {};
const gf = item.generated_fields || {};
const missingFields = item.generation_missing_fields || [];

const theShift = `Enabling shift: ${a.enabling_shift || ''}`;

const nationalWedge = [dc.fit_rationale || '', dc.local_wedge ? ('Wedge: ' + dc.local_wedge) : ''].filter(Boolean).join(' ');

const existingPlayersStr = (dc.existing_players || []).join(', ') || 'None evidenced';
const criteria = sc.criteria || [];
const diffCriterion = criteria.find(c => c.name === 'Differentiation vs. existing national players');
const defCriterion = criteria.find(c => c.name === 'Defensibility / moat');

const generatedWhyRelevant = (gf.why_relevant || '').trim();
const whyRelevant = generatedWhyRelevant.length > 0
  ? generatedWhyRelevant
  : `Existing players: ${existingPlayersStr}. Differentiation score: ${diffCriterion ? diffCriterion.score + '/5' : 'n/a'}. Defensibility score: ${defCriterion ? defCriterion.score + '/5' : 'n/a'}.`;

const shortlistEligible = (typeof sc.weighted_total === 'number' && sc.weighted_total >= 60) && ['medium', 'high'].includes(sc.confidence_band);

const generatedName = (gf.name || '').trim();
const finalName = generatedName.length > 0 ? generatedName : ('Idea ' + item.idea_number);

// Rule-based sovereign/long-horizon lever classification (reorders by actionability)
const SOVEREIGN_KEYWORDS = /\b(fusion|quantum|advanced nuclear|nuclear energy|space propulsion|rocket|launch vehicle|satellite constellation|longevity|geroscience|gene therapy|biotech breakthrough|novel materials|materials science|semiconductor fab|advanced semiconductor|hard[- ]?tech|deep[- ]?tech|sovereign wealth|frontier research)\b/i;
const classifyText = [a.category, a.pattern, a.transferable_thesis].filter(Boolean).join(' ');
const sovereignLever = SOVEREIGN_KEYWORDS.test(classifyText);

// Normalize act_watch_kill to exactly one of the three values
const rawDecision = (gf.act_watch_kill || '').trim().toLowerCase();
let actWatchKill = 'Watch';
if (rawDecision.startsWith('act')) actWatchKill = 'Act';
else if (rawDecision.startsWith('kill')) actWatchKill = 'Kill';
else if (rawDecision.startsWith('watch')) actWatchKill = 'Watch';

const owningEntity = (gf.owning_entity || '').trim() || (dc.anchor_buyer || '').trim() || 'Not specified';
const next90Days = (gf.next_90_days || '').trim();
const executionLevel = (gf.execution_level || '').trim() || 'national';

const fields = {
  name: finalName,
  one_liner: gf.one_liner || '',
  the_shift: theShift,
  national_wedge: nationalWedge,
  what_it_is: gf.what_it_is || '',
  who_pays: dc.anchor_buyer || '',
  why_defensible: whyRelevant,
  what_it_takes: gf.what_it_takes || '',
  why_it_might_fail: gf.why_it_might_fail || '',
  score_breakdown: {
    criteria: criteria,
    weighted_total: sc.weighted_total,
    confidence_band: sc.confidence_band
  },
  firm_lens: gf.firm_lens || '',
  shortlist_eligible: shortlistEligible,
  owning_entity: owningEntity,
  execution_level: executionLevel,
  act_watch_kill: actWatchKill,
  next_90_days: next90Days,
  sovereign_lever: sovereignLever
};

const criteriaMd = criteria.map(c => `- ${c.name}: ${c.score}/5 (${c.evidence_ref})`).join('\n');

const renderedMarkdown = [
  `# ${fields.name}`,
  fields.one_liner,
  '',
  `**Recommendation: ${fields.act_watch_kill}** | Owning entity: ${fields.owning_entity} (${fields.execution_level}) | Sovereign lever: ${fields.sovereign_lever ? 'Yes' : 'No'}`,
  fields.next_90_days ? `Next 90 days: ${fields.next_90_days}` : '',
  '',
  '## The Shift', fields.the_shift,
  '', '## National Wedge', fields.national_wedge,
  '', '## What It Is', fields.what_it_is,
  '', '## Who Pays', fields.who_pays,
  '', '## Why Relevant', fields.why_defensible,
  '', '## What It Takes', fields.what_it_takes,
  '', '## Why It Might Fail', fields.why_it_might_fail,
  '', '## Score Breakdown',
  `Weighted Total: ${fields.score_breakdown.weighted_total}/100 (Confidence: ${fields.score_breakdown.confidence_band})`,
  criteriaMd,
  '', '## Firm Lens', fields.firm_lens,
  '', `Shortlist eligible: ${fields.shortlist_eligible ? 'Yes' : 'No'}`
].join('\n');

return [{ json: {
  idea_id: item.idea_id,
  one_pager_json: {
    fields: fields,
    rendered_markdown: renderedMarkdown,
    generated_at: new Date().toISOString(),
    generation_missing_fields: missingFields
  }
} }];
